    ToggleButton toggleButton = (ToggleButton) view;
    isCameraRotationEnable = !isCameraRotationEnable;
    if (toggleButton.isChecked())
        map.getSettings().setMapRotationEnabled(true);
    else
        map.getSettings().setMapRotationEnabled(false);
}
