    map.on("load", () => {
        map.addSource(SOURCE_ID, {
            type: "geojson",
            data: makeRandomPoints(420),
            cluster: true,
            clusterRadius: 60,
            clusterMaxZoom: 15,
        });

        map.addLayer({
