      container: containerRef.current,
      style,
      center: [51.383743,35.701150],
      zoom: 12,
      apiKey,
    });

    return () => {
      mapRef.current?.remove();
      mapRef.current = null;
    };
  }, [apiKey, style]);

  return <div ref={containerRef} style={{ position: "absolute", inset: 0 }} />;
}
```

